REPLACE INTO `music_artist` (`id`, `name`, `realName`, `avatar`, `cover`, `createUserId`, `pinyin`, `firstLetter`, `gender`, `area`, `description`, `sort`, `isHot`, `enabled`, `createdAt`, `updatedAt`) VALUES
	(10001, '周杰伦', '周杰伦', 10001, 10002, 9999999999, NULL, NULL, 'MALE', 'CN_TW', '周杰伦（Jay Chou），1979年1月18日出生于台湾省新北市，祖籍福建省永春县，华语流行乐男歌手、原创音乐人、影视演员、导演、编剧，毕业于淡江中学 [1]。\n演艺经历：周杰伦自幼喜爱音乐 [30]，后因参加选秀节目而被发掘 [35]。2000年，发行个人首张音乐专辑《Jay》并获得广泛关注 [2-3]。2001年，凭借音乐专辑《范特西》奠定其在华语乐坛的地位与影响力 [4-5]，并因此收获多个重要的主流音乐奖项 [38]。凭借音乐成就，他先是于2003年登上美国《时代》杂志封面 [6]，此后推出《叶惠美》《七里香》《11月的萧邦》《依然范特西》等商业与口碑兼具的音乐专辑 [7-10]，并因主演个人首部电影《头文字D》进军影坛 [13]。2007年成立“杰威尔音乐有限公司”后 [15]，持续产出《我很忙》《魔杰座》《跨时代》《哎呦，不错哦》《周杰伦的床边故事》等多张关注度较高的音乐专辑 [18-23]，首度自编自导并主演的爱情片《不能说的秘密》更取得出人意料的高票房成绩 [16-17]。2019年，为迎接出道20周年而开始举行周杰伦“嘉年华”世界巡回演唱会 [25]。2026年，发行音乐专辑《太阳之子》 [600]。', 2, 1, 1, '2026-09-23 12:56:04', '2026-10-11 09:14:19'),
	(10002, '雪桜草', '雪桜奈帆，如月秋祐', 10003, 10004, 9999999999, NULL, NULL, 'BAND_GROUP', 'JP', '2008年成立的同人音乐社团\n雪桜草是日本同人音乐社团，成立于2008年，由Key社粉丝自发组成。社团以改编Key社游戏原声音乐为核心，融合原创歌词并由主唱YuKi、SAKURA等演绎，核心成员包括运营负责人雪桜奈帆、主唱Sou、作词编曲如月秋祐与藤村ろい等，分工涵盖作曲、混音及美术设计 [1]。\n社团初期以改编Key社经典曲目为主，推出《Nostalgia -Mirage of Key-》《Kanon ～远い日の雪～》等专辑，其中《Nostalgia -Mirage of Key-》为2013年发行的首张精选集 [4]。2010年发布专辑《Chranos ～クラノス～》 [5]。2011年后扩展原创内容，发布《More than Words》等作品，并参与《Air Violin》合作企划。2011年发行专辑《planetarian ～ちいさなほしのうた～》 [2-3]。主唱阵容逐步形成双女声与男声结合的体系，代表作包括《夏影》《鸟の诗 -Primal Sky-》等。歌曲《渚～君と目指した高み、願いが叶う場所～》的词作者为Akihiro Kisara，原曲作者为Maeda Jun [6]。通过实体CD发行及粉丝社区互动，社团在2013至2021年间持续活跃，作品通过贴吧等平台传播', 1, 0, 1, '2026-09-23 23:21:35', '2026-10-11 09:15:04'),
	(10005, '三无marblue', '三无marblue', 10005, 10006, 9999999999, NULL, NULL, 'FEMALE', 'CN_MAINLAND', '三无marblue，女，1992年12月6日出生，是一名翻唱爱好者、哔哩哔哩音乐类up主 [10] [43]，哔哩哔哩2018、2019百大UP主。被粉丝称为“三月月”、“老大”。拥有多条声线，能够在少年音、少女音与御姐音中自如切换，声线辨识度较高，代表作《深夜诗人》、《心生七面 善恶难辨》 [1-2] [43]。\n2016年，发行单曲《权御天下》 [36]。2018年5月23日，演唱了阴阳师面灵气同人曲《心生七面 善恶难辨》 [4]；同年12月20日，与hanser、泠鸢yousa 、茶理理共同演唱了原创国风歌曲《千里邀月》 [5]。2019年9月23日，演唱了国风音乐企划【侠·心】系列的原创国风歌曲《虚传》 [3]。2021年8月14日，三无marblue发行了单曲《石头歌》 [37]。10月15日，她又发行了单曲《夏末与童年》 [38]。11月10日，三无marblue与他人共同发行了合唱单曲《他》 [39]。2023年1月15日，三无marblue发行合唱专辑《百战成诗2023》 [40]。同月18日，三无marblue发行专辑《敢归云间宿》 [41]。', 4, 0, 1, '2026-09-23 23:25:46', '2026-10-11 09:15:30'),
	(10006, '花丸はれる', '花丸はれる', 10007, 10008, 9999999999, NULL, NULL, 'FEMALE', 'JP', '花丸晴琉（日文名：花丸はれる/Hanamaru Hareru），女性虚拟偶像，2019年8月1日作为花寄女生宿舍成员开始活动，2025年3月9日宣布无限期停止活动 [3-4]。生日为3月20日，身高154厘米，官方形象以橙色右侧单马尾发型搭配绿白条纹发巾为特征 [1]。\n作为以歌唱见长的虚拟主播，花丸晴琉在Bilibili平台拥有44.5万粉丝，其代表作包括播放量达514.9万的《日语版〈芒种〉翻唱》、282.0万播放的《日语版〈孤勇者〉翻唱》以及129.7万播放的《学猫叫》中日双语版翻唱 [11]。2021年参与B站创世之音虚拟演唱会时曾用中文演唱《芒种》 [5]。2021年至2022年间更新过白色连衣裙、蓝白色连衣裙两套服装造型 [1]。在2023年至2024年期间，还发布了《絆ノ奇跡》《小悪魔だってかまわない!》《偶像》等多首翻唱作品 [13]。\n2025年2月18日官方发布活动休止预告视频，最终于3月9日通过直播及《致我重要的人们》翻唱视频正式进入休眠状态。停止活动前进行了多场Bilibili限定歌回直播，并推出包含四季造型的首部收藏集', 1, 0, 1, '2026-09-23 23:27:27', '2026-10-11 09:16:05'),
	(10007, '泠鳶yousa', '泠鳶yousa', 10009, 10010, 9999999999, NULL, NULL, 'FEMALE', 'CN_MAINLAND', '泠鸢yousa，女，生日5月19日，居于成都，脱胎于三次元真人的虚拟艺人，中国本土原创最具人气的虚拟偶像之一。 [1-2]品种不详的一只鸟，人类语言的发音掌握得不太好，但非常喜欢与人说话，也经常怀疑自己就是人。 [3]直播时说话经常吃螺丝，因此调侃自己是在水下直播。 [4]左耳处有一缕长发（逗猫辫），为了逗猫而留的 [5]，声音软萌多才多艺，擅长词创作及演唱填词，作曲、演唱、配音、绘画、后期全能。 [6-7]\n原为虚拟艺人团体VirtuaReal Star成员、哔哩哔哩歌手UP主、直播签约主播，连续4年（2018-2021）获评哔哩哔哩百大UP主。 [8-9] [84]2016年8月15日，发行首张个人原创专辑《茜色诗集》。 [16] [88]2019年12月21日，在成都 BW2019发行原创个人专辑《折纸信笺》。 [10]', 6, 0, 1, '2026-10-11 09:17:46', '2026-10-11 09:17:46'),
	(10008, '茶理理', '茶理理', 10011, 10012, 9999999999, NULL, NULL, 'FEMALE', 'CN_MAINLAND', '茶理理（Chalili），中国内地唱见，哔哩哔哩知名UP主 [6]，7月3日出生于湖南省长沙市，毕业于美国南加利福尼亚大学，曾赴早稻田大学交换学习。声线多变，选曲风格多样，性格低调随和。作为虚拟歌手星尘的音源提供者，代表作品包含原创曲《La Vanille》及翻唱曲《活动小丑 - 英文版》《About Me》等，能娴熟演绎日、英文曲目。2013年10月19日在5sing平台发布翻唱作品《柒寒》，2014年1月于哔哩哔哩投稿首支作品《え?あぁ、そう》，2015年2月11日在5sing平台发布《千本樱》 [7]。2016年参与虚拟歌手星尘音源录制及专辑《星愿StarWish》制作，2019年发行个人专辑《被抹去的女孩》。2020年发布单曲《星愿》，2021年推出单曲《光》。2022年1月28日发行单曲《冰雪回响》。2021年为《崩坏3》动画短片《薪炎永燃》演唱印象曲《Moon Halo》 [1]，2023年演唱单曲《Reburn》 [2]、为《崩坏：星穹铁道》演唱公测主题曲中文版《星间旅行》 [3]，并为游戏《银河境界线》演唱角色曲《Ashen Dawn》 [4]。曾参与《Blessing - World Edition》《Connecting - World Edition》国际合唱企划，热门作品涵盖《童话镇/Tong Hua Zhen cover》《Firewill》《Lost And Found - 〈夜猫快递之黑日梦〉网剧插曲》等 [5]。', 1, 0, 1, '2026-10-11 09:18:40', '2026-10-11 09:18:40'),
	(10009, 'Hanser', 'Hanser', 10013, 10014, 9999999999, NULL, NULL, 'FEMALE', 'CN_MAINLAND', 'Hanser，女，中国内地配音演员、bilibiliUP主 [65] [74] [81]。2011年3月22日，hanser发布了在B站的第一个视频“这个歌姬叫猫柳”。于2018年、2020年、2021年，入选bilibili年度百大UP主 [19] [42-45] [57]。2019年12月14日，她有了自己的虚拟形象。2020年12月20日，正式宣布加入VirtuaReal Star [46]。2021年9月7日，小爱同学上线了Hanser定制语音包。2021年10月3日，于杭州运河大剧院参与个人演唱会《海上油菜花》 [57]。2022年8月27日，参与《崩坏3》“纯真梦歌”线上音乐会。2022年9月20日，发布首张个人音乐专辑《一抹憨色》电子版上线网易云。2023年7月29日，hanser参与的《崩坏3》“林海绮律”线上音乐会开播 [74]。为《崩坏：星穹铁道》中的银狼配音 [81]。2025年，发布原创曲如《中古店爱情》等 [86]。2025年11月21日，与游戏《重构:阿塔提斯》联动 [87]。2026年4月27日，发行单曲《速通满级攻略》。 [89]8月2日，发行单曲《我独自满级》。 [91]8月22~23日，在上海静安体育中心参与个人类演唱会《花生与葱花', 1, 0, 1, '2026-10-11 09:19:36', '2026-10-11 09:19:36'),
	(10010, '逃跑计划', '逃跑计划', 10015, 10016, 9999999999, NULL, NULL, 'BAND_GROUP', 'CN_MAINLAND', '逃跑计划乐队（Escape Plan），中国内地流行摇滚乐队，成立于2004年，由主唱毛川、吉他手马晓东、贝斯手刚昂、鼓手王非凡、键盘手曲锐组成 [7]。\n2004年底，逃跑计划乐队的前身“孔雀乐队”正式成立。2007年，乐队更名为“逃跑计划” [39]。2008年，因受邀出席迷笛音乐节而开始受到业内的关注，并发行乐队首张迷你音乐专辑《Take Me Away》 [7]；同年，获得星光大典“最具潜力乐队奖” [39]。2009年，获得“盖世群音”乐队音乐大赛北京区总决赛冠军 [2]。2011年，发行乐队首张音乐专辑《世界》 [75]，并凭借该专辑和专辑歌曲《夜空中最亮的星》获得广泛关注 [76]。2012年，在第4届中国摇滚迷笛奖中同时获得四个奖项 [5]。2014年，获得微博之夜“微博年度风尚奖” [31]。2015年，在台北国际会议中心举办演唱会 [14]；此后，由于创作方向迷失，乐队的第二张音乐专辑迟迟未能面世 [76]。2019年，作为首发歌手参加音乐竞技节目《歌手2019》 [27]。2021年，发行乐队第二张音乐专辑《回到海洋》 [28]，并获得第3届腾讯音乐娱乐盛典“年度最佳乐队奖', 1, 0, 1, '2026-10-11 09:21:30', '2026-10-11 09:21:30'),
	(10011, '双笙', '双笙', 10031, 10032, 9999999999, NULL, NULL, 'FEMALE', 'CN_MAINLAND', '双笙，本名陈元汐，2000年5月13日出生于重庆市开州区，中国内地古风女歌手 [49]。\n2015年6月，在原创音乐网站5sing网上发布翻唱的古风歌曲《故梦》 [1]；同年，发行原创歌曲《采茶纪》 [2]。2016年，发行专辑《笙声不息》。2017年3月，发行为古典小说《红楼梦（青春版）》演唱的推广曲《终身误》。2018年11月3日，获得“网易云音乐国风极乐夜”国风音乐人最受欢迎女歌手奖 [3]；同年，与GAI合作，为手游《中国惊奇先生》演唱的主题曲《都市惊奇夜》；同年，发行为电影《阴阳诀之祭情》演唱的主题曲《阴阳诀》；同年，发行歌曲《谢芳菲》。2019年4月20日，获得“少年中国”国风音乐节暨“青年人最喜爱的国风音乐”颁奖典礼歌唱人奖 [5]。', 1, 0, 1, '2026-10-11 09:47:57', '2026-10-11 09:47:57');
